if (IsInRdgMode())
{
    if (f("tmp_dob").toBoolean())
    {
        var startDate = new Date(1975, 0, 1);   // 01/01/2020
        var endDate   = new Date(2025, 11, 31); // 31/12/2025

        var randomTime = startDate.getTime() + Math.random() * (endDate.getTime() - startDate.getTime());
        var randomDate = new Date(randomTime);

        var dd = ("0" + randomDate.getDate()).slice(-2);
        var mm = ("0" + (randomDate.getMonth() + 1)).slice(-2);
        var yyyy = randomDate.getFullYear();

        f("tmp_dob").set(dd + "/" + mm + "/" + yyyy);
    }
}

