// add to custom validation for all JavaScript DK/REF questions
function setDKREF() {
  const qnIndex = String(a('qn_dkref'))
    .split(',')
    .map(s => s.trim())
    .filter(s => s.length > 0)
    .map(Number)
    .filter(Number.isFinite);
  const qnIndexSort = [...qnIndex].sort((a, b) => a - b);

  // check if question already exists and clear data
  qnIndexSort.forEach(val => {
      if (f('qn_dkref_' + val + '_other').get() == CurrentForm()) {
          f('qn_dkref_' + val).set(null);
          f('qn_dkref_' + val + '_other').set(null);
      }
  });

  // set if question is dk/ref
  const getnrv = f(CurrentForm()).getNoResponseValue();
  if (getnrv != null) {
    for (let val of qnIndexSort) {
      if (!f('qn_dkref_' + val + '_other').toBoolean()) {
        f('qn_dkref_' + val).set(getnrv);
        f('qn_dkref_' + val + '_other').set(CurrentForm());
        break;
      }
    }
  }
}

// converts text to hyperlink
// USE:
// - asLink("https://www.srcentre.com.au") = <a href="https://www.srcentre.com.au" target="_blank">https://www.srcentre.com.au</a>
// - asLink("https://www.srcentre.com.au","Click here!") = <a href="https://www.srcentre.com.au" target="_blank">Click here!</a>
// - asLink("ttan@srcentre.com.au") = <a href="mailto:ttan@srcentre.com.au">ttan@srcentre.com.au</a>
function asLink(link, linkText) {
    if (!linkText) linkText = link;
    var islink = /https?:\/\/[^\s<>"']+/;
    if (IsEmail(link)) {
        return "<a href='mailto:" + link + "'>" + linkText + "</a>";
    } else if (islink.test(link)) {
        return "<a href='" + link + "' target='_blank'>" + linkText + "</a>";
    }
    return link;
}

