function getAusDateTime() {
    const date = new Date();
    const offSet = 11; // 10 for AEST, 11 for AEDT
    const offsetUTC = offSet * 60 * 60 * 1000;
    const ausDate = new Date(date.getTime() + offsetUTC);

    const myDate = f('insertdate').toBoolean() ? new Date(f('insertdate').get()) : ausDate;
    return new Date(myDate.toLocaleString("en-AU", {
        timeZone: "Australia/Sydney"
    }));
}

