function getausdatetimezone() {
    const sydneyNow = new Date(
        new Date().toLocaleString("en-AU", {
            timeZone: "Australia/Sydney"
        })
    );
    const offSet = 11; // 10 for AEST, 11 for AEDT

    return Math.floor(
        (new Date(f('insertdate').get()) - sydneyNow) / offSet * 60 * 60 * 1000
    ) >= 0;
}

function copyq(to,fr) 
{
    var prec = f(fr).domainValues(); 
    for (var i = 0; i < prec.length; i++) {
        var code = prec[i];
        if (f(fr).item(code).toBoolean()) 
        {
            f(to).item(code).set(f(fr).item(code).get());
        }
    }
}



function maskemail(qid) 
{
    var parts = f(qid).get().split('@');
    var local = parts[0];
    var domain = parts[1];

    if (local.length <= 2) {
        return local + '@' + domain;
    }

    return local.substring(0, 2) +
        'x'.repeat(local.length - 2) +
        '@' + domain;
}


function maskmobile(qid) {
    var mobile = f(qid).get();
    return mobile.substring(0, 2) +
           'x'.repeat(Math.max(0, mobile.length - 5)) +
           mobile.substring(mobile. length - 3);
}



function maskname(qid) {
    var name = f(qid).get();

    return name.split(' ').map(function(word) {
        var masked = '';

        for (var i = 0; i < word.length; i++) {
            if (i === 0 || (i % 4 === 0)) {
                masked += word.charAt(i);
            } else {
                masked += '*';
            }
        }

        return masked;
    }).join(' ');
}

function skipcode(qid) {
    var skipCode = "1000";
    if (f(qid).getType() == 'COMPOUND') {
        var form = f(qid);
        var codes = form.domainValues();
        for (var i = 0; i < codes.length; i++) {
            var code = codes[i];
            if (form.item(code).DICHOTOMY) {
                if (!f(qid).toBoolean()) {
                    //Multi select
                    f(qid).item(skipCode).set('1');
                }
            }
            else if (form.item(code).OPEN || form.item(code).NUMERIC) {//do nothing for text box
            }
            else //grid
            {
                if (!f(qid).item(code).toBoolean()) {
                    f(qid).item(code).set(skipCode);
                }
            }
        }
    }
    else if (f(qid).getType() == 'CODED' && !f(qid).toBoolean()) //single select
    {
        f(qid).set(skipCode);
    }
    else {
    }
}

