function getProjectSettings(name) {
  const projectSettings = {
    // This might not be the same as the src_job_id. 
    // If you need to dedupe across multiple separate Forsta surveys, you would set them
    // all to have the same value below
    DEDUPE_PROJECT_CODE: "SRC3497",
    // set as a single string, NO spaces
    //e.g. LinA, ORU, Octopus, Pureprofile, Lightspeed, Open (for open link), Client
    PANEL_NAME: "Client",
    // Set the country code for whehre the survey is running. Is used by RD to detect country mismatches and 
    // block respondents for entering the survey
    // NZ for New Zealand etc (Can only set to one single country)
    COUNTRY_CODE: "AU",
    // Controls whether the screen containing Research Defender is automatically submitted
    // once the API queries have completed or the timeout is reached, whichever happens first.
    //
    // Useful when Research Defender is placed on an intermediate screen and respondents
    // should continue automatically without clicking Next.
    AUTO_SUBMIT: false,
  };
  return projectSettings[name];
}

/*
  Uncomment the relevant config below, appropriate for the sample source being used for the project.
  Currently supported types are:
    - LinA
    - Client sample with/without incentives
    - Non-probability panel / MMM / Polaron
    - Commercial list sample with/without incentives
    - A-BS push-to-web
    - RDD SMS push-to-web
    - Open link / social media **WITHOUT** incentives
    - Open link / social media **WITH** incentives
*/

// - LinA
// - Client sample with/without incentives
function getRDConfig(name) {
  const configs = {
    FAIL_ON_API_ERROR: false,
    THREAT_POTENTIAL_THRESHOLD: false,
    DUPLICATE_SCORE_THRESHOLD: false,
    COUNTRY_MISMATCH_CHECK: false,
    ACTIVITY_FAIL_ON_API_ERROR: false,
    ACTIVITY_COUNT_THRESHOLD: false,
  };
  return configs[name];
}

