const questions = [
    'MBS_RP',
    'MBS_Consent',
    'MBS_sal',
    'MBS_first_name',
    'MBS_family_name',
    'MBS_other_name',
    'MBS_dob',
    'MBS_medicare_cardno',
    'MBS_primary_add',
    'MBS_sec_add',
    'MBS_authorisation',
    'MBS_consent2',
    'MBS_signature1',
    'MBS_datesign1',
    'MBS_g_first_name',
    'MBS_g_second_name',
    'MBS_signature2',
    'MBS_datesign2',
    'MBS_rel'
];

const anyAnswered = questions.some(q =>
    f(q).toBoolean()
);

var missingFields = [];

if (anyAnswered) {

	if (!f('MBS_RP').toBoolean() || f('MBS_RP').size() !== 6) {
		missingFields.push('Rights and Privacy');
	}

	if (!f('MBS_Consent').toBoolean()) {
		missingFields.push('Consent');
	}

	if (!f('MBS_first_name').toBoolean()) {
		missingFields.push('Legal first name');
	}

	if (f('MBS_first_name').toBoolean() &&
		!f('MBS_sal').toBoolean()) {
		missingFields.push('Mr/Mrs/Ms/Miss/Other');
	}

	if (f('MBS_first_name').toBoolean() &&
		!f('MBS_family_name').toBoolean()) {
		missingFields.push('Family name');
	}

	if (!f('MBS_dob').toBoolean()) {
		missingFields.push('Date of birth');
	}

	if (!f('MBS_medicare_cardno').toBoolean()) {
		missingFields.push('Medicare card number (first 9 digits only)');
	}

	if (!f('MBS_primary_add').toBoolean()) {
		missingFields.push('Primary address');
	}

	if (!f('MBS_authorisation').toBoolean()) {
		missingFields.push('Authorisation');
	}

	if (!f('MBS_signature1').toBoolean() || !f('MBS_datesign1').toBoolean()) {
		if (f('MBS_rel').toBoolean()) {
			if (!f('MBS_g_first_name').toBoolean() || !f('MBS_signature2').toBoolean() || !f('MBS_datesign2').toBoolean()) {
				missingFields.push('Participant sign and date and/or, Guardian / POA name, sign and date');
			}
		} else {
			missingFields.push('Participant sign and date');
		}
	}
	/* not compulsory
	if (f('MBS_rel').toBoolean()) {
		missingFields.push('Legal Guardian / POA relation');
	}
	*/

	if (missingFields.length > 0) {

		var missingList = '<ul><li>' +
			missingFields.join('</li><li>') +
			'</li></ul>';


		RaiseError();
		ClearErrorMessage();
		ClearQuestionErrorMessage();

		SetQuestionErrorMessage(
			LangIDs.en_au,
			'To enable data linkage, all required fields must be completed. ' +
			'Please provide your response for:' +
			missingList
		);
	}
}

if (QuestionErrors()>0) {
	f(CurrentForm()).set('1');
} else {
	f(CurrentForm()).set(null);
}

