Single.StartupScript:
const incomplete = "^f('CL_incomplete').any('1')^" == "True";

if (incomplete) {

    [
        'CL_sal',
        'CL_family_name',
        'CL_first_name',
        'CL_dob',
        'CL_res_addr',
        'CL_consent'
    ].forEach(function(qid) {
        const $label = $('#' + qid + '_text');
        $label.html("<span class='mandatory' style='color:red'>*</span>" + $label.html());
    });

    /*
     * If Guardian/POA declaration has been started,
     * require Guardian fields.
     */
    if ("^f('CL_rel').toBoolean()^" == "True") {

        [
            'CL_signature2',
            'CL_datesign2',
            'CL_rel'
        ].forEach(function(qid) {
            const $label = $('#' + qid + '_text');
            $label.html("<span class='mandatory' style='color:red'>*</span>" + $label.html());
        });

        /*
         * Supporting evidence required for
         * Legal guardian / POA / Guardianship order
         */
        if ("^f('CL_rel').any('2','3','4')^" == "True") {
            $('#CL_sup_file_text').html(
                "<span class='mandatory' style='color:red'>*</span>" +
                $('#CL_sup_file_text').html()
            );
        }

    } else {

        [
            'CL_signature1',
            'CL_datesign1'
        ].forEach(function(qid) {
            const $label = $('#' + qid + '_text');
            $label.html("<span class='mandatory' style='color:red'>*</span>" + $label.html());
        });
    }
}

Single.ValidationCode:
const questions = [
    'CL_sal',
    'CL_family_name',
    'CL_first_name',
    'CL_second_name',
    'CL_dob',
    'CL_CRN',
    'CL_othername',
    'CL_home_phone_no',
    'CL_work_phone_no',
    'CL_mobile_phone_no',
    'CL_email',
    'CL_res_addr',
    'CL_postal_addr',
    'CL_consent',
    'CL_signature1',
    'CL_datesign1',
    'CL_signature2',
    'CL_datesign2',
    'CL_rel',
    'CL_sup_file'
];

const anyAnswered = questions.some(q =>
    f(q).toBoolean()
);

var missingFields = [];

if (anyAnswered) {

    if (!f('CL_sal').toBoolean()) {
        missingFields.push('Mr/Mrs/Ms/Miss/Other');
    }

    if (!f('CL_family_name').toBoolean()) {
        missingFields.push('Family name');
    }

    if (!f('CL_first_name').toBoolean()) {
        missingFields.push('Legal first given name');
    }

    if (!f('CL_dob').toBoolean()) {
        missingFields.push('Date of birth');
    }

    if (!f('CL_res_addr').toBoolean()) {
        missingFields.push('Residential address');
    }

    if (!f('CL_consent').toBoolean() || f('CL_consent').size() !== 2) {
        missingFields.push('Centrelink payment consent');
    }

    if (!f('CL_signature1').toBoolean() || !f('CL_datesign1').toBoolean()) {
        if (f('CL_rel').toBoolean()) {
            if (!f('CL_signature2').toBoolean() || !f('CL_datesign2').toBoolean()) {
                missingFields.push('Participant sign and date and/or Parent/Guardian/POA relationship, sign and date');
            }
        } else {
            missingFields.push('Participant sign and date');
        }
    }

    if (f('CL_rel').any('2','3','4') && !f('CL_sup_file').toBoolean()) {
        missingFields.push(
            'Supporting evidence for Legal Guardian/POA'
        );
    }

    if (missingFields.length > 0) {

        var missingList =
            '<ul><li>' +
            missingFields.join('</li><li>') +
            '</li></ul>';

        RaiseError();
        ClearErrorMessage();
        ClearQuestionErrorMessage();

        SetQuestionErrorMessage(
            LangIDs.en_au,
            'To enable data linkage, all required fields must be completed. ' +
            'Please provide your response for:' +
            missingList
        );
    }

}
if (QuestionErrors()>0) {
	f(CurrentForm()).set('1');
} else {
	f(CurrentForm()).set(null);
}

