        'NDI_first_name',
        'NDI_family_name',
        'NDI_dob',
        'NDI_primary_add',
        'NDI_signature1',
        'NDI_datesign1'
    ].forEach(function(qid) {
        const $label = $('#' + qid + '_text');

        if (!$label.find('.mandatory').length) {
            $label.html(
                "<span class='mandatory' style='color:red'>*</span>" +
                $label.html()
            );
        }
    });
}

Single.ValidationCode:
const questions = [
    'NDI_consent',
    'NDI_sal',
    'NDI_first_name',
    'NDI_family_name',
    'NDI_other_name',
    'NDI_dob',
    'NDI_primary_add',
    'NDI_postal_add',
    'NDI_signature1',
    'NDI_datesign1'
];

const anyAnswered = questions.some(q =>
    f(q).toBoolean()
);

var missingFields = [];

if (anyAnswered) {

    if (!f('NDI_consent').toBoolean() || f('NDI_consent').size() !== 6) {
        missingFields.push('Consent');
    }

    if (!f('NDI_sal').toBoolean()) {
        missingFields.push('Mr/Mrs/Ms/Miss/Other');
    }

    if (!f('NDI_first_name').toBoolean()) {
        missingFields.push('First name');
    }

    if (!f('NDI_family_name').toBoolean()) {
        missingFields.push('Family name');
    }

    if (!f('NDI_dob').toBoolean()) {
        missingFields.push('Date of birth');
    }

    if (!f('NDI_primary_add').toBoolean()) {
        missingFields.push('Primary address');
    }

    if (!f('NDI_signature1').toBoolean() ||
        !f('NDI_datesign1').toBoolean()) {
        missingFields.push('Sign and date');
    }

    if (missingFields.length > 0) {

        var missingList =
            '<ul><li>' +
            missingFields.join('</li><li>') +
            '</li></ul>';

        RaiseError();
        ClearErrorMessage();
        ClearQuestionErrorMessage();

        SetQuestionErrorMessage(
            LangIDs.en_au,
            'To enable data linkage, all required fields must be completed. Please provide your response for:' +
            missingList
        );
    }
}
if (QuestionErrors()>0) {
	f(CurrentForm()).set('1');
} else {
	f(CurrentForm()).set(null);
}

