Please sign below:
<br/><i>Once done with Sign, please click on 'Save' button to submit signature.</i>


<div class="wrapper">
  <canvas id="signature-pad" class="signature-pad" width=400 height=200></canvas>
</div>

<button type="button" id="save">Save</button>
<button type="button" id="clear">Clear</button>


<style>
//.cf-open-answer__input {display:none;}
#^CurrentForm()^_content {display:none}
.wrapper {
  position: relative;
  width: 400px;
  height: 200px;
  -moz-user-select: none;
  -webkit-user-select: none;
  -ms-user-select: none;
  user-select: none;
margin-bottom: 5px;

}

@media (max-width: 680px){
.wrapper, #signature-pad {
  width: 100% !important;
}
}

.signature-pad {
  position: absolute;
  left: 0;
  top: 0;
  width:400px;
  height:200px;
  background-color: white;
border: 1px solid green;
}
</style>

Open.StartupScript:
var canvas = document.getElementById('signature-pad');

// Adjust canvas coordinate space taking into account pixel ratio,
// to make it look crisp on mobile devices.
// This also causes canvas to be cleared.
function resizeCanvas() {

    // When zoomed out to less than 100%, for some very strange reason,
    // some browsers report devicePixelRatio as less than 1
    // and only part of the canvas is cleared then.
    var ratio = Math.max(window.devicePixelRatio || 1, 1);
    canvas.width = canvas.offsetWidth * ratio;
    canvas.height = canvas.offsetHeight * ratio;
    canvas.getContext("2d").scale(ratio, ratio);
    signaturePad.clear();
}
var signaturePad = new SignaturePad(canvas, {
    backgroundColor: 'rgb(255, 255, 255)' // necessary for saving image as JPEG; can be removed is only saving as PNG or SVG
});

window.onresize = resizeCanvas;
resizeCanvas();




document.getElementById('save').addEventListener('click', function () {
    if (signaturePad.isEmpty()) {
        return alert("Please provide a signature first.");
    }
    currentQuestion.setValue(canvas.toDataURL('image/svg+xml'))
    setTimeout(function () {
        updatePreview(imageUrl);
    }, 1000);
});

document.getElementById('clear').addEventListener('click', function () {
    signaturePad.clear();
    //currentQuestion.setValue("", "");
});

function updatePreview(value) {

    const container = document.getElementById('signaturePreview');

    container.innerHTML = '';

    if (!value) {
        return;
    }

    const img = document.createElement('img');
    img.width = 100;
    img.src = value;

    container.appendChild(img);
}

