Script.ScriptCode:
f('NDI_completed').set('completed')
SetRespondentValue('NDI_completed',f('NDI_completed'))
AddResponentToSurvey("p477835092108", getUserId(), "AllModules", "Started");

var surveyId = "p734908116504"; // 3464 Comcare NF
if (f('userid').toBoolean()) {
  var userid = f('userid').get();

  if (userid.includes('_') && userid.length > 2) {
    userid = userid.slice(0, -2);
  }
  f('chkuserid').set(userid);
}
function getSurveyId() {
  return "p734908116504"
}
function getUserId() {
  return f('chkuserid').get()
}

function AddResponentToSurvey(surveyId, userid, moduleNum, surveystatus) {
    try {
        var access_token = Authenticate();
        var endpoint = "https://surveys.srcentre.com.au/v1/surveys/" + surveyId + "/respondents/data";

        var headers = { Authorization: "redacted" + access_token };
        //var match = GetSurveyName().match(/Module\w+/);
        //var moduleName = match ? match[0] : null;

        //if (f('userid').toBoolean()) {
        //    var userid = f('userid').get();

            if (userid.includes('_') && userid.length > 2) {
                userid = userid.slice(0, -2);
            }
        //    f('chkuserid').set(userid);
        //}

        var payload = {
            dataSchema: {
                keys: ["Respid"],
                variables: ["Respid", moduleNum]
            },
            data: [
                { respid: userid, [moduleNum]: surveystatus}
            ]
        };

        //f('payloadstr').set(JSON.stringify(payload)); //for debug

        var result = Http.PatchJson(endpoint, payload, headers);
        var resultJson = (typeof result === "string") ? JSON.parse(result) : result;
        //var insertedIds = resultJson && resultJson.insertedIds;
        var respId = userid;
        /*
            (Array.isArray(insertedIds) ? insertedIds[0] : undefined) ||
            resultJson?.insertedId ||
            resultJson?.id ||
            resultJson?.respondentId;
        */
        f("Response3").set(JSON.stringify({ raw: resultJson, respId: respId })); //for debug

        if (!respId) {
            return false;
        }

        //var uniqueURL = GetRespondentLink(surveyId, respId);
        //return (typeof uniqueURL === "string") ? uniqueURL : (uniqueURL?.url || "Error: No valid URL returned.");

    } catch (e) {
        var errInfo = (e && e.stack) ? e.stack : String(e);
        f("Response3").set(errInfo + " catch");
        return false;
    }
}

function Authenticate() {

    var clientId = "redacted";
    var clientSecret = "redacted";

    var auendpoint = "https://surveys.srcentre.com.au/identity/connect/token";
    var data = "client_id=" + clientId + "&client_secret="redacted"&grant_type=api-user&scope=pub.surveys";
    var result = Http.Post(auendpoint, data, null);

    var decoded = JSON.parse(result);
    if (!decoded.access_token || decoded.access_token == null || decoded.access_token == undefined) {
        return null;
    }
    return decoded.access_token;
}

/**API DOCUMENT CAN BE FOUND BELOW**/
//https://kleberwebsite.datatoolscloud.net.au/kleberbrowser/KleberMethodDescription.aspx?Method=DataTools.Security.GenerateTemporaryRequestKey



function getKleberToken (pld, returnKey=false) {
    if (!f(pld).toBoolean() || (f(pld).toBoolean() && !testKleberToken(f(pld).get()))) {
        //Request the tempory key
        const requestString =  "https://kleber.datatoolscloud.net.au/KleberWebService/DtKleberService.svc/ProcessQueryStringRequest?Method=DataTools.Security.GenerateTemporaryRequestKey&ExpirySeconds=600&RequestId=&RequestKey=redacted&DepartmentCode=1111";
        var response = Http.Post(requestString,"","");

        // Find the starting and ending points of the key
        const startTag = 'TemporaryRequestKey="';
        const startIndex = response.indexOf(startTag) + startTag.length;
        const endIndex = response.indexOf('"', startIndex);

        // Extract the key
        const temporaryRequestKey = response.substring(startIndex, endIndex);

        //var jsonresult=JSON.parse(response)]
        f(pld).set(temporaryRequestKey)
    };
    return returnKey ? f(pld).get() : null;
}

function testKleberToken(token) {

    try {

        const testUrl =
            "https://kleber.datatoolscloud.net.au/KleberWebService/DtKleberService.svc/ProcessQueryStringRequest" +
            "?Method=DataTools.Capture.Address.Predictive.AuPaf.SearchAddress" +
            "&AddressLine=test" +
            "&ResultLimit=1" +
            "&SearchOption=A002" +
            "&RequestId=" +
            "&RequestKey=" + token +
            "&DepartmentCode=1" +
            "&OutputFormat=json";

        var response = Http.Get(testUrl);

        return response.indexOf("Invalid Request Key") == -1;

    }
    catch(e) {
        return false;
    }
}

