Script.ScriptCode:
var respState = GetRespondentValue('resp_state');

if ((respState == null || respState === '') || respState != f('AppState')) {
    SetRespondentValue('resp_state', f('AppState'));
}

 //if not blank, update the TelephoneNumber for next call
if (f('Preferred_number').toBoolean()) 
{
    //Set number for next call
    SetRespondentValue('TelephoneNumber',f('Preferred_number'));

    //dialler_phone_1 is the initial number for TelephoneNumber, so new numbers start from dialler_phone_2   
    // List of dialler phone variables
    var diallerPhones = [f('dialler_phone').get(), f('dialler_phone_2').get(), f('dialler_phone_3').get(), f('dialler_phone_4').get(), f('dialler_phone_5').get(), f('dialler_phone_6').get()];
    var preferredNumber = f('preferred_number').get();

    // Check if preferred_number exists in the list
    var exists = diallerPhones.includes(preferredNumber);

    if (!exists) {
        // Find the first empty variable and assign preferred_number to it
        for (var i = 1; i < diallerPhones.length; i++) {
            if (diallerPhones[i] === null || diallerPhones[i] === "") {
                SetRespondentValue('dialler_phone_' + (i + 1), preferredNumber);
                SetRespondentValue('active_dialler_phone', 'dialler_phone_' + (i + 1));
                break;
            }
        }
    } else {
        // If exist, write the sample field name to active_dialler_phone
        for (var i = 0; i < diallerPhones.length; i++) {
            if (diallerPhones[i] === preferredNumber) {
                if (i == 0) {
                    SetRespondentValue('active_dialler_phone','dialler_phone');
                } else {
                    SetRespondentValue('active_dialler_phone','dialler_phone_' + (i + 1));
                }           
                break;
            }
        }

    }

    f('Preferred_number').set(null);

}

//Update sample field for stopped by script
if (GetExtendedStatus() == 13 || GetExtendedStatus() == 32) {
    f('FinalOutcome').set('1'); //Completed
}

//example to set FinalOutcome:
//if (f('IN1').any('3') || f('INT4').any('3')) {
//    f('FinalOutcome').set('4'); //LOTE - no follow up
//}


//Other contacts: 71-80
/*if (f('Intro6').any('3') || f('Intro7').any('4')) {
    f('FinalOutcome').set('5'); //Proxy does not know enough to provide information
    SetExtendedStatus('71')
}*/


//Screen out: 81-90
/*if (f('Count_Name').toNumber()>=3) {
    f('FinalOutcome').set('9'); //REF_SCHOOL (if three times invalid)
    SetExtendedStatus('81')
}*/


//Refusal: 91-100
/*if (f('MOBSAFE').any('3')) {
    f('FinalOutcome').set('2'); //Household refusal
    SetExtendedStatus('92')
}*/

//Update queue, previous_queue, has_made_contact, screener sample fields
//Completed
if (GetExtendedStatus() == 13) {
    SetRespondentValue('queue','COMPLETED');
    SetRespondentValue('has_made_contact','1');
}
//No answer
else if (GetExtendedStatus() == 3) {
    SetRespondentValue('queue','RECALL');
}
//Answering machine - message left
else if (GetExtendedStatus() == 7) {
    SetRespondentValue('queue','RECALL');
} 
//Answering machine - No message left
else if (GetExtendedStatus() == 50) {
    SetRespondentValue('queue', 'RECALL');
}
//Engaged/busy
else if (GetExtendedStatus() == 2) {
    SetRespondentValue('queue','RECALL');
}
//LOTE - follow up required
else if (GetExtendedStatus() == 36) {
    SetRespondentValue('queue','RECALL');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('lote_flag','1')
}
//Hard Appointment
else if (GetExtendedStatus() == 1) {
    SetRespondentValue('queue','APPOINTMENT');
    SetRespondentValue('has_made_contact','1');
}
//Soft Appointment
else if (GetExtendedStatus() == 33) {
    SetRespondentValue('queue','APPOINTMENT');
    SetRespondentValue('has_made_contact','1');
}
//Respondent refusal: 5, 91-100
else if (GetExtendedStatus() == 5 || (GetExtendedStatus() >= 91 && GetExtendedStatus() <= 100)) {
    SetRespondentValue('queue','REFUSED');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('screener','Failed');
}
//Over quota
else if (GetExtendedStatus() == 4) {
    SetRespondentValue('queue','OVERQUOTA');
    SetRespondentValue('screener','Failed');
}
//Survey script error
else if (GetExtendedStatus() == 1051) {
    SetRespondentValue('queue','FAILED');
    SetRespondentValue('has_made_contact','1');
}
//Agreed to complete online
else if (GetExtendedStatus() == 20) {
    SetRespondentValue('queue','TRANSFER_TO_WEB');
    SetRespondentValue('has_made_contact','1');
}
//UNUSABLE
//Fax
else if (GetExtendedStatus() == 9) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','0');
}
//Number disconnected
else if (GetExtendedStatus() == 11) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','0');
}
//Deceased
else if (GetExtendedStatus() == 40) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//Business number/Not a residential number
else if (GetExtendedStatus() == 60) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//RESIDENTIAL_NUMBER/Not a business number
else if (GetExtendedStatus() == 61) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//Named person / organisation not known
else if (GetExtendedStatus() == 62) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//Midway termination
else if (GetExtendedStatus() == 6) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//DNCR/Remove number from list
else if (GetExtendedStatus() == 17) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//Not available/Away for duration
else if (GetExtendedStatus() == 34) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//LOTE - no follow up
else if (GetExtendedStatus() == 35) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('lote_flag','2')
}
//Too old / frail / ill-health
else if (GetExtendedStatus() == 37) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//Unreliable respondent / drunk
else if (GetExtendedStatus() == 38) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//Claims to have done survey
else if (GetExtendedStatus() == 39) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//No-one 18 plus in household
else if (GetExtendedStatus() == 41) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('screener','Failed');
}
//Incoming call restriction
else if (GetExtendedStatus() == 56) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','0');
}
//FailedScreener: 81 to 90
else if (GetExtendedStatus() == 14 || (GetExtendedStatus() >= 81 && GetExtendedStatus() <= 90)) {
    SetRespondentValue('queue', 'UNUSABLE');
    SetRespondentValue('has_made_contact', '1');
    SetRespondentValue('screener', 'Failed');

    if (GetSurveyChannel() == "Cawi") {
        AddRespondentToCati(GetExtendedStatus());
    }
}

//Other contacts (within survey script): 71 to 80
else if (GetExtendedStatus()>=71 && GetExtendedStatus()<=80) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('screener','Failed');
    SetStatus("screened");
}
//Early complete
if (GetRespondentValue("EarlyCompFlg")=="Y") {
    SetRespondentValue('queue','COMPLETED');
    SetRespondentValue('has_made_contact','1');
};


f('queue').set(GetRespondentValue('queue'));
f('has_made_contact').set(GetRespondentValue('has_made_contact'));
f('screener').set(GetRespondentValue('screener'));
SetRespondentValue('extended_status',GetExtendedStatus());

//var iter = f('TotalAttempts').get();
//var iter = GetTotalAttempts();
var iter = f('total_attempt_count');
iter = iter * 1;

// do Duration
var start = new Date(InterviewStart().getTime());
var now = new Date();
var duration = (now.getTime() - start.getTime()) / 1000;
f('session_duration',iter).set(Math.round(duration));

// update interview mode
//f('interview_mode',iter).set(GetSurveyChannel()=="Cati" ? '2' : '1');

// do ExtendedStatus
if (GetExtendedStatus()>=1)
{
    f('contact_extended_status',iter).set(GetExtendedStatus());
    f('LastContactExtendedStatus').set(f('contact_extended_status',iter).valueLabel());
    SetRespondentValue ('extended_status',GetExtendedStatus());
    f('extended_status').set(GetExtendedStatus());
}

// update endQ
f('session_endQ',iter).set(f('endQ'));

//CATI only fields
if (GetSurveyChannel()=="Cati"|| f("Mode").get()=="2")
{
    // do Interviewer ID
    f('call_inter_ID',iter).set(GetCatiInterviewerId());

    // do Interviewer Name/login
    f('call_inter_name',iter).set(GetCatiInterviewerName());

       //do Interviewer Display name
    f('call_inter_display',iter).set(GetCatiInterviewerDisplayName());

    // do Comments
    if (f('Comments').toBoolean())
    {
        f('call_comments',iter).set(f('Comments'));
        f('Comments').set(null); 
    }

    //call_ref_rr1
    /*if (f('RR1').toBoolean()) 
    {
        f('call_ref_rr1',iter).set(f('RR1').valueLabel());
    }*/

    //call_ref_rr2
    /*if (f('RR2').toBoolean()) 
    {
        if (f('RR2').any('1')) {
            f('call_ref_rr2',iter).set('Hard refusal');
        }
        else if (f('RR2').any('2')) {
            f('call_ref_rr2',iter).set('Soft refusal');
        }    
    }*/

    //call_Ref_con
    f('call_ref_con',iter).set(f('ref_con'));    
}


// Apptime
if (GetExtendedStatus()==1 || GetExtendedStatus()==33 || GetExtendedStatus()==32)
{
    f('call_app_time',iter).set(GetCatiAppointmentTime())
}
else
{
    f('call_app_time',iter).set(null)
}

var qid = "Timestamp";
var rng = f(qid).categories();
var qidTotal = "Timestamp_tot";

var tot_time = 0;

for (var i=0; i<rng.length; i++) {
    var cd = rng[i];
    var qid2 = qid + "_" + cd;

    if (f(qid2).toBoolean() && f(qid2).toNumber()>0) {
        tot_time = Sum(tot_time,f(qid2).toNumber());
    }
}
if (tot_time > 0) f(qidTotal).set(tot_time);

SetInterviewEnd()

const date = new Date(InterviewEnd()); 
var offSet = 11 
//var offSet = 10 //Daylight saving enabled
var offsetUTC = offSet*60*60*1000; 
const ausDate = new Date(date.getTime()+offsetUTC); 
//example output: Saturday 12 October 2024 4:43:32 pm
f('End_Time').set(ausDate.toLocaleString('en-AU', { timezone: 'Australia/Sydney', hour12: false }))
//example output: 12/10/2024 5:39:53 pm
//f('End_Time').set(ausDate)


const int_date = new Date(f('End_Time'))
//in DD/MM/YYYY format
var int_dd = int_date.getDate().toString()
if (int_dd.length == 1) { int_dd = "0" + int_dd }
var int_mm = (int_date.getMonth()+1).toString()
if (int_mm.length == 1) { int_mm = "0" + int_mm }
var int_yyyy = int_date.getFullYear().toString()
f('IntDate').set( int_dd + "/" + int_mm + "/" + int_yyyy)


var options = { hour12: false, hourCycle: 'h23', hour: '2-digit', minute: '2-digit', second: '2-digit' };
var currentTime = ausDate.toLocaleTimeString('en-AU', options);
f('IntTime').set(currentTime);
